-- Verified source snapshot. Existing editorial changes are preserved.
insert into public.portfolio_projects (slug,title,subtitle,description,technologies,category,repository_url,live_url,cover_image,gallery,featured,published,sort_order,content)
select slug,title,subtitle,description,technologies,category,repository_url,live_url,cover_image,gallery,featured,published,sort_order,content
from jsonb_to_recordset('[{"slug":"camicurt","title":"CAMÍ CURT","subtitle":"A small route. A surprisingly deep problem.","description":"A Catalan geography game that turns the comarca map into a daily graph puzzle.","category":"INTERACTIVE WEB / ALGORITHMS","technologies":["React","D3","TopoJSON","Graph algorithms","Supabase"],"repository_url":"https://github.com/drpauu/camicurt.cat","live_url":"https://camicurt.cat","cover_image":"/images/cami-curt.webp","gallery":[],"featured":true,"published":true,"sort_order":1,"content":{"status":"Live","intro":"Find the connection. Discover the territory.","problem":"A map can teach much more than names. The challenge is to make geographic relationships tangible, playful and worth returning to.","approach":"Players connect two Catalan comarques through adjacent territories, with rules requiring or forbidding particular regions. Dijkstra enumerates optimal routes; A* provides a complementary length check. The SVG map makes the graph visible and gives feedback on every move.","architecture":["Comarca geometry → TopoJSON + D3","Adjacency graph → Dijkstra + rule validation","Web Worker → shortest-path cache","React → interactive SVG map","Supabase → shared daily calendar"],"challenges":[{"title":"Turn a graph into something intuitive","description":"Geometric territories act as selectable graph nodes. Route feedback connects the player’s choices with an optimal path."},{"title":"Make a daily challenge dependable","description":"A shared daily calendar has a local generation fallback. A Web Worker precomputes route caches while the main thread keeps the map responsive. Normal, time-trial and exploration modes complement the daily challenge."}],"scope":"Live application. The installation uses the game’s 41-region geographic dataset. That dataset is not presented as a claim of current administrative completeness. Portfolio interactions stay local and do not access player sessions.","source":"Public source reviewed at 612657b: README.md, src/lib/pathfinding.js and src/lib/geography.js; matching local game data and worker inspected.","caption":"Actual public Camí Curt application · captured without signing in."}},{"slug":"athra","title":"ATHRA","subtitle":"From training data to a clearer picture.","description":"An athlete analytics application connecting FIT imports, training load and recovery indicators in one place.","category":"SPORTS DATA / ANALYTICS","technologies":["TypeScript","React","Express","Garmin FIT SDK","Recharts"],"repository_url":"https://github.com/drpauu/athra","live_url":null,"cover_image":"/images/athra.webp","gallery":[],"featured":true,"published":true,"sort_order":2,"content":{"status":"Development prototype","intro":"Performance starts with understanding the signal.","problem":"Training produces a lot of data. Interpreting activity, sleep and recovery together should not require jumping between disconnected tools.","approach":"ATHRA imports Garmin FIT files, normalizes activity records and calculates versioned, deterministic recovery and training-load indicators. The interface brings those calculations into focused views for daily readiness, activities, sleep and trends.","architecture":["Garmin FIT files → validated upload","FIT SDK → normalized activity records","Repository interface → in-memory implementation","Recovery engine → Express API","React + Recharts → athlete dashboard"],"challenges":[{"title":"Keep the calculation inspectable","description":"The recovery engine computes HRV baselines, resting heart-rate deviation and exponentially weighted training load in ordinary TypeScript. The calculation is separate from the optional AI coaching integration."},{"title":"Preserve the provenance","description":"The importer and data explorer retain a route back to imported activity records. A repository interface separates ingestion, calculations and presentation."}],"scope":"The current checkout uses an in-memory repository. Durable persistence and production authentication are further work. Recovery indicators are product calculations, not clinically validated conclusions.","source":"Source reviewed at c755f20: App.tsx, fit-importer.ts, recovery-engine.ts, api.ts and server.ts.","caption":"Actual local application · repository demonstration data, not personal health records."}},{"slug":"alcoholfabet","title":"ALCOHOLFABET","subtitle":"A playful surface. A deliberate system underneath.","description":"A Catalan question-based board game with in-person and online play, server-validated turns and synchronized sessions.","category":"MULTIPLAYER / INTERACTION DESIGN","technologies":["TypeScript","React","SVG","Supabase","PostgreSQL","Realtime"],"repository_url":"https://github.com/drpauu/Alcoholfabet","live_url":"https://alcoholfabet.cat","cover_image":"/images/alcoholfabet.webp","gallery":[],"featured":true,"published":true,"sort_order":3,"content":{"status":"Live","intro":"The board is playful. The rules stay consistent.","problem":"A shared board game needs one trustworthy sequence of turns, whether both players share a screen or join from separate devices. Questions, answers and actions also need to respect each player’s role.","approach":"React presents a tactile SVG board, pieces and question cards. The browser sends action requests to PostgreSQL functions through Supabase; the server validates the move and returns a view appropriate to the viewer. Private Realtime channels notify connected devices when the session changes.","architecture":["React + SVG → board and turn presentation","Validated action request → Supabase RPC","PostgreSQL → authoritative game state","Role-aware view → safe answer visibility","Private Realtime channel → refreshed session"],"challenges":[{"title":"Keep the answer on the right side of the table","description":"Server views control which role can see an answer or judge a response. The client validates the returned shape and rejects responses that expose an answer to a responding player."},{"title":"Make a turn survive reconnection","description":"State versions and idempotency keys support consistent actions. The session reducer and private channel recover the authoritative view after interruptions, while the motion system follows explicit game phases."}],"scope":"The public application includes in-person play; online roles require private player codes. These capabilities were inspected in source. No production game was created or modified during portfolio verification. The installation is an illustration, not a live game session.","source":"Public repository and local source match d184832: game-repository.ts, useGameSession.ts, useGameChannel.ts, game rules and SQL migrations reviewed.","caption":"Actual Alcoholfabet interface · isolated menu fixture with an empty score; no production game or auth session opened."}},{"slug":"trackflow","title":"TRACKFLOW","subtitle":"A training week, with everything connected.","description":"A planning application bringing coaches, athletes and weekly training into a shared workflow.","category":"PRODUCT ENGINEERING / SYSTEMS","technologies":["React","Vite","Express","MongoDB","Playwright"],"repository_url":"https://github.com/drpauu/TrackFlow","live_url":null,"cover_image":"/images/trackflow.webp","gallery":[],"featured":true,"published":true,"sort_order":4,"content":{"status":"Source available","intro":"Structure for the work behind performance.","problem":"A training plan needs to stay useful after it is written: a coach publishes a week, athletes follow their sessions, and both need an up-to-date view.","approach":"TrackFlow pairs a React frontend with an Express API and MongoDB persistence. Weekly plans project into athlete day plans and completion states; incremental synchronization refreshes only the changed storage keys.","architecture":["Coach / athlete → React interface","Same-origin /api → Express","Storage contract → compatibility cache","Canonical model → MongoDB collections","Monotonic syncVersion → incremental refresh"],"challenges":[{"title":"Evolve the model without replacing the UI","description":"A compatibility layer preserves the existing tf_* storage contract while projecting writes into a canonical MongoDB data model."},{"title":"Keep every athlete in the right context","description":"Records and synchronization are scoped by coachId. A published week becomes daily plans and completion states used by the athlete calendar."}],"scope":"The previous public deployment is unavailable. This case study describes the implemented planning and synchronization architecture. Authentication hardening and broader regression coverage remain areas for continued improvement.","source":"Source reviewed at 1b730d6: README.md, frontend/src and server/src.","caption":"Actual local application · unauthenticated entry screen. No athlete records displayed."}}]'::jsonb) as p(slug text,title text,subtitle text,description text,technologies text[],category text,repository_url text,live_url text,cover_image text,gallery jsonb,featured boolean,published boolean,sort_order integer,content jsonb)
on conflict(slug) do nothing;
